import{_ as i,a as t,b as l,c as s,d as e,e as r,f as o,g as c,h as n,i as d,j as m,k as p,l as u,m as h}from"./chunks/gs_13.D_z1_q-r.js";import{_ as f,c as _,o as g,ae as b}from"./chunks/framework.Cd-3tpCq.js";const B=JSON.parse('{"title":"快速开始","description":"快速开始使用 MinecraftSounds 创建你的第一个音乐包","frontmatter":{"title":"快速开始","description":"快速开始使用 MinecraftSounds 创建你的第一个音乐包"},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),k={name:"guide/getting-started.md"};function q(M,a,S,P,x,v){return g(),_("div",null,a[0]||(a[0]=[b('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本指南将帮助你快速上手 MinecraftSounds，创建你的第一个我的世界音乐包。</p><h2 id="安装-minecraftsounds-音频包生成器" tabindex="-1">安装 MinecraftSounds 音频包生成器 <a class="header-anchor" href="#安装-minecraftsounds-音频包生成器" aria-label="Permalink to &quot;安装 MinecraftSounds 音频包生成器&quot;">​</a></h2><h3 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h3><ul><li>Windows 10 或以上版本</li><li>1GB 内存</li><li>500MB 可用磁盘空间</li></ul><h3 id="下载-minecraftsounds-音频包生成器" tabindex="-1">下载 MinecraftSounds 音频包生成器 <a class="header-anchor" href="#下载-minecraftsounds-音频包生成器" aria-label="Permalink to &quot;下载 MinecraftSounds 音频包生成器&quot;">​</a></h3><ol><li>前往<a href="/download.html">下载页面</a>获取最新版本的 MinecraftSounds 音频包生成器</li><li>下载压缩包（例如：MinecraftSounds.zip 或 MinecraftSounds.7z）</li><li>解压压缩包到你选择的目录（例如：D:\\MinecraftSounds）</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>请检查解压后的内容跟图片是不是一样的 <img src="'+i+'" alt="解压内容"></p></div><h2 id="创建你的第一个音乐包" tabindex="-1">创建你的第一个音乐包 <a class="header-anchor" href="#创建你的第一个音乐包" aria-label="Permalink to &quot;创建你的第一个音乐包&quot;">​</a></h2><h3 id="启动-minecraftsounds-音频包生成器" tabindex="-1">启动 MinecraftSounds 音频包生成器 <a class="header-anchor" href="#启动-minecraftsounds-音频包生成器" aria-label="Permalink to &quot;启动 MinecraftSounds 音频包生成器&quot;">​</a></h3><p>启动应用程序。首次启动时，你会看到一个文件格式关联提示。</p><p><img src="'+t+'" alt="创建项目"></p><p>按照提示操作，将 MinecraftSounds 音频包生成器 关联到 .mcsd 文件格式。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>关联完成后，你可以直接双击 .mcsd 文件来打开程序。</p></div><h3 id="创建新项目" tabindex="-1">创建新项目 <a class="header-anchor" href="#创建新项目" aria-label="Permalink to &quot;创建新项目&quot;">​</a></h3><ol><li>点击「新建项目」按钮 <img src="'+l+'" alt="创建项目"></li><li>在弹出的 新建项目 的窗口里填写信息 <img src="'+s+'" alt="创建项目"></li><li>确认信息无误后，点击「确认」按钮 <img src="'+e+'" alt="创建项目"></li><li>在二次确认弹窗中，点击「创建」按钮 <img src="'+r+'" alt="创建项目"></li><li>项目创建完成后，会切换到编辑页面，弹窗「项目创建成功」可以点击「确定」关闭弹窗。 <img src="'+o+'" alt="创建项目"></li></ol><h3 id="添加音效" tabindex="-1">添加音效 <a class="header-anchor" href="#添加音效" aria-label="Permalink to &quot;添加音效&quot;">​</a></h3><p>现在，你可以开始添加自定义音效了：</p><ol><li>点击「选择文件」按钮，在弹出的文件选择窗口中，选择你要添加的音频文件 <img src="'+c+'" alt="创建项目"></li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>仅支持添加 .ogg、.wav、.mp3、.flac 格式的音频文件</p></div><ol start="2"><li>添加的音频文件会显示在下方列表中，你可以在列表中查看已添加的音频文件 <img src="'+n+'" alt="创建项目"></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>Minecraft 官方仅支持 .ogg 格式的音频文件。导出的时候程序会自动将其他格式转换为 .ogg 格式。</p></div><h3 id="导出音乐包" tabindex="-1">导出音乐包 <a class="header-anchor" href="#导出音乐包" aria-label="Permalink to &quot;导出音乐包&quot;">​</a></h3><p>当你对音乐包满意后，可以将其导出为 Minecraft 可用的资源包：</p><ol><li>点击顶部菜单的「导出」按钮 <img src="'+d+'" alt="创建项目"></li><li>点击底部的「开始导出」按钮，程序就会开始按照上方的步骤开始执行。 <img src="'+m+'" alt="创建项目"></li><li>导出成功后会弹窗提醒，点击「确定」按钮关闭弹窗。 <img src="'+p+'" alt="创建项目"></li><li>点击左下角的「打开文件夹」按钮，会打开存放打包后的音频包的文件夹 <img src="'+u+'" alt="创建项目"></li></ol><div class="warning custom-block"><p class="custom-block-title">提示</p><p>如果程序没有打开文件夹，你可以通过输出的「已打开文件夹」后面的路径找到。<br> 你也可以从路径：<code>{软件目录}\\_internal\\app\\projects\\{你填写音乐包名称}\\dist</code>找到 <img src="'+h+'" alt="创建项目"></p></div><h2 id="安装音乐包到-minecraft" tabindex="-1">安装音乐包到 Minecraft <a class="header-anchor" href="#安装音乐包到-minecraft" aria-label="Permalink to &quot;安装音乐包到 Minecraft&quot;">​</a></h2><ol><li>打开 Minecraft</li><li>点击「选项」→「资源包」</li><li>点击「打开资源包文件夹」</li><li>将导出的 .zip 文件复制到此文件夹</li><li>返回 Minecraft，你的音乐包应该出现在可用资源包列表中</li><li>点击「→」按钮将其移动到「已选资源包」列表</li><li>点击「完成」按钮</li></ol><p>现在，你可以在游戏中使用你自定义的音效或音乐了！</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>探索<a href="/tutorials/">教程</a>部分，学习如何创建更复杂的音乐包</li></ul>',31)]))}const $=f(k,[["render",q]]);export{B as __pageData,$ as default};
